/* Design simulation only. No game engine, network, browser storage, random or persistence. */
const A='../editable/assets/';
const qs=new URLSearchParams(location.search);
let screen=SCREENS.find(x=>x.id===qs.get('screen'))||SCREENS.find(x=>x.id==='P03-hospital');
let active={...screen}, tool=screen.tool||null, specialty=screen.specialty||null, expanded=!!screen.max, stage=screen.stage||0, reduced=!!screen.reduced;
let carryTab=screen.id==='P10-equipment'||['setup','hub'].includes(screen.kind)?'equipment':'backpack';
let contextNode=screen.node, backScreen={...screen};
let chosen={}, feedback=screen.kind==='error'?'当前记录未就绪；没有可执行的玩法。':'当前地点可自由查看；查看详情不消耗精力。', lastFocus=null, lastFocusAction=null, lastFocusLabel=null, sceneOnly=false, drawer=null;
const $=s=>document.querySelector(s);
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const img=(file,alt,cls='')=>`<img src="${A+file}" alt="${escape(alt)}" class="${cls}">`;
const btn=(label,action,cls='',extra='')=>`<button class="${cls}" data-act="${action}" ${extra}>${label}</button>`;
const itemImg=k=>img(ITEMS[k][1],ITEMS[k][0]);
const facts=rows=>`<div class="facts">${rows.map(([a,b])=>`<div class="fact"><span>${a}</span><b>${b}</b></div>`).join('')}</div>`;
const note=text=>`<div class="note">${text}</div>`;
const fields=(title,values,key)=>`<label>${title}<select data-field="${key}"><option value="">请选择</option>${values.map((v,i)=>`<option value="${i}" ${String(chosen[key])===String(i)?"selected":""}>${v}</option>`).join('')}</select></label>`;
const art=(file,alt,scene=false)=>`<div class="artwell ${scene?'scene':''}">${img(file,alt)}</div>`;
const FOCALS={H3:[23,42],H7:[80,42],T1:[88,45],P1:[66,45],L0:[50,50],L1:[16,45],L5:[88,45],C4:[77,45],C5:[85,45]};
const focal=()=>FOCALS[active.node]||[50,42];
function actorVisual(file,label,role){const r=REGISTERED[file],c=r.imageCss;return `<div class="actor ${role}" data-foot="0.5,0.92" data-hit="${r.hitNormalized}"><img class="actor-raster" src="${A+file}" alt="${label}" style="left:${c.left}%;top:${c.top}%;width:${c.width}%">${role==='enemy'?`<img src="${A}fx-hit-v1.png" class="hit-flash" alt="独立命中叠图" style="left:${r.hitNormalized[0]*100}%;top:${r.hitNormalized[1]*100}%">`:''}</div>`;}
const node=()=>NODES[context?.node||active.node]||NODES.H0;
const variant=()=>active.id.substring(4);
function enemyFile(enemy,phase){const names=['pristine','wounded','heavy_wounded','critical','disabled'];return enemy==='orderly'?`enemy_infected_orderly_${names[phase]}_v02.png`:`enemy-${enemy}-${names[phase]}-v1.png`;}
function knownMap(large=false){
 const region=context.node?.[0]||'H';
 let ids=region==='T'?['H0','T0','T1']:region==='P'?['T0','P0','P1']:region==='L'?['H7','L0','L1']:region==='C'?['L0','C0','C1']:['H0','H1','H2','H3','H4'];
 if(active.node==='H5')ids=['H3','H4','H5'];
 if(region==='L'&&active.node!=='L0')ids=['L0','L1',active.node==='L1'?'L2':active.node];
 if(region==='C'&&active.node!=='C0')ids=['C0','C1',active.node==='C1'?'C2':active.node];
 if(active.node==='H6')ids=['H1','H3','H6'];
 if(active.node==='H7')ids=['H0','H1','H7'];
 if(active.node==='H8')ids=['H1','H7','H8'];
 if(active.node==='C3')ids=['C1','C2','C3'];
 const xy=ids.length===3?[[80,180],[250,180],[420,180]]:[[80,180],[230,180],[230,80],[230,290],[410,180]];
 const paths=ids.length===3?'M80 180H420':'M80 180H230V80 M230 180V290';
 return `<svg class="${large?'maplarge':'minimap'}" viewBox="0 0 500 360" role="img" aria-label="只读已知${node()[0]}拓扑"><path class="mapline" d="${paths}"/>${ids.length===5?`<path class="mapline ${variant()==='blocked'?'blocked':''}" d="M230 180H410"/>`:""}${ids.map((id,i)=>`<circle class="mapnode ${id===active.node?'current':''}" cx="${xy[i][0]}" cy="${xy[i][1]}" r="${large?10:12}"/><text class="maptext ${id===active.node?'current':''}" x="${xy[i][0]}" y="${xy[i][1]+32}" text-anchor="middle">${large?NODES[id][1]:({H0:'前室',H1:'大厅',H2:'药房',H3:'保安',H4:'隔离',H5:'冷藏',H6:'值班',H7:'后勤',H8:'转运',T0:'入口',T1:'安置',P0:'配线',P1:'支路',L0:'岗亭',L1:'登记',L2:'装卸',L3:'维修',L5:'休息',C0:'入口',C1:'档案',C2:'检修',C3:'机房',C4:'检修间',C5:'侧门'})[id]||NODES[id][1]}</text>`).join('')}${large?`<text class="maptext" x="320" y="150">${variant()==='unknown-passability'?'通行未知':variant()==='last-observed'?'上次观察':variant()==='blocked'?'已知受阻':''}</text>`:''}</svg>`;
}
function sampleItems(active){
 const variant=()=>active.id.substring(4);
 const entry=(k,x,y,q=1,w=ITEMS[k][2],h=ITEMS[k][3])=>[k,x,y,w,h,q];
 if(['setup','hub','error'].includes(active.kind)||active.family==='P21'||active.id==='P14-death')return [];
 if(active.kind==='node'){if(active.id==='P06-install')return [entry('component',0,0),entry('module',2,0),entry('metal',3,0),entry('electronic',4,0)];if(active.id==='P06-component-result')return [entry('component',0,0)];if(active.id==='P06-sample-result')return [entry('sample',0,0)];return [];}
 if(active.kind==='terminal')return [entry('firstaid',0,0),entry('ration',1,0,2),entry('metal',2,0,2),entry('battery',3,0)];
 if(active.kind==='medical')return active.battle?[]:[entry(active.item||'bandage',0,0)];
 if(active.kind==='maintenance')return variant()==='coat'?[entry('cloth',0,0)]:variant()==='toolbox'?[entry('metal',0,0),entry('electronic',1,0)]:variant()==='charge'?[entry('battery',0,0)]:[entry('metal',0,0)];
 if(active.kind==='npc')return active.person==='lin'?[entry('bandage',0,0),entry('disinfectant',1,0)]:[];
 if(active.kind==='organize')return variant()==='task-pickup'?[]:variant()==='drop'?[entry('sample',0,0)]:variant()==='merge'?[entry('bandage',0,0),entry('bandage',1,0)]:variant()==='no-space'?[entry('bandage',0,0),entry('firstaid',1,0),entry('module',2,0),entry('metal',3,0),entry('battery',4,0),entry('ration',5,0),entry('cloth',0,1),entry('disinfectant',3,1),entry('electronic',4,1),entry('coat',0,2),entry('toolbox',2,2),entry('component',4,2)]:[entry('bandage',0,0,2)];
 if(active.rotated)return [entry('crow',0,0,1,3,1),entry('sample',3,1),entry('bandage',0,2)];
 return [...(active.kind==='mission'&&['ground','delivered'].includes(variant())?[]:[entry('sample',0,0)]),entry('firstaid',2,0),entry('ration',3,0,2),entry('metal',4,0,2),entry('battery',5,0),...(active.id==='P08-delivered'?[]:[entry('card',3,1)])];
}
function designItems(){return context.items.map(i=>[i.key,i.x,i.y,i.w,i.h,i.quantity]);}
function designWeight(){const weights={pipe:3,coat:2,crow:3,lamp:1,toolbox:4,firstaid:2,sample:4,component:4,module:2,card:0};return designItems().reduce((sum,[k,x,y,w,h,q])=>sum+(weights[k]??1)*q,0);}
function grid(selection=false){const entries=designItems();
return `<div class="inventory ${selection?'selection-grid':''}" aria-label="背包6列4行" data-grid><div class="slots" style="display:contents">${Array.from({length:24},(_,i)=>`<${selection?'button':'div'} class="slot" ${selection?`data-act="cell:${i}" aria-label="第${i%6+1}列第${Math.floor(i/6)+1}行"`:''}></${selection?'button':'div'}>`).join('')}</div>${entries.map(([k,x,y,w,h,q],i)=>`<button class="item ${active.rotated&&k==='crow'?'rotated':''}" data-act="item:${k}" data-object-key="${k}" data-object-ref="${context.items[i].ref}" data-container="backpack" aria-label="${ITEMS[k][0]}，${w}乘${h}格，打开详情" style="--x:${x};--y:${y};--w:${w};--h:${h}">${itemImg(k)}<span class="quantity">${q}</span></button>`).join('')}</div>`;}
function equipment(){
 if(context.error)return note('记录尚未就绪，不显示假定装备。');if(context.dead)return note('当前实物不可用；历史处分保留，不向新角色继承。');
 const keys=['pipe',...(context.coatEquipped?['coat']:[]),...(tool?[tool]:[])],maxes={pipe:30,coat:12,crow:12,lamp:8,toolbox:6};
 return `<div class="equipment">${keys.map(k=>{const cur=context.resources[k],max=maxes[k];return `<button class="equip" data-act="item:${k}" data-object-key="${k}" data-container="equipment">${itemImg(k)}<span class="grow"><span class="spread"><b>${ITEMS[k][0]}</b><small>${cur}/${max}</small></span><span class="resource"><i style="width:${cur/max*100}%"></i></span></span></button>`;}).join('')}${!tool?'<p class="muted">工具尚未选择</p>':''}</div>`;
}

function quick(){if(context.error||context.dead)return note('当前快捷物品不可用。');return `<div class="quick">${btn(`${itemImg('bandage')}<span>绷带 ×1<br><small>快捷位 1</small></span>`,'quick:bandage','','data-object-key="bandage" data-container="quick"')}${btn('<span class="muted">空槽<br><small>快捷位 2</small></span>','quick:empty')}</div>`;}

function shell(){const n=node(),dead=context.dead,initial=context.initial;return `<div class="shell ${context.error?'error-mode':''} ${reduced?'reduce-motion':''}">
<header class="hud metal"><div class="brand">电梯求生</div><div class="day"><small>任务日</small> <b>${context.day}</b><small> / 7</small></div><div class="compact-tabs">${btn('目标','drawer:left','small')}${btn('携带','drawer:right','small')}</div><div class="hud-stat"><span>生命</span><b>${context.hp} / 12</b><span class="meter red"><i style="width:${context.error?0:Number(context.hp)/12*100}%"></i></span></div><div class="hud-stat"><span>精力</span><b>${context.energy} / 100</b><span class="meter gold"><i style="width:${context.error?0:context.energy}%"></i></span></div><div class="hud-stat"><span>饱食</span><b>${context.satiety} / 6</b><span class="meter"><i style="width:${context.error?0:Number(context.satiety)/6*100}%"></i></span></div><div class="hud-end"><small class="healthlabel">${context.error?'身体状态未就绪':dead?'角色已死亡':initial?'未达病程损耗档':'低病程负担'}</small>${btn('身体','help:health','small')}${btn('帮助','help:controls','small help')}</div></header>
<aside class="sidebar left metal ${drawer==='left'?'open':''}">${btn('关闭目标栏','drawer:none','small drawer-close')}<div class="side-title">当前委托</div><div><p class="eyebrow">封锁区</p><h2 class="mission-title">未完成的转运</h2></div><p style="font-size:15px">恢复本地供电与转运，携指定样本返回电梯前室。</p><div class="objectives"><p><i class="dot"></i><span>本地供电<span class="muted"> · ${context.powerDone?'已完成':'未完成'}</span></span></p><p><i class="dot"></i><span>转运设施<span class="muted"> · ${context.transferDone?'已完成':'未完成'}</span></span></p><p><i class="dot"></i><span>指定样本<span class="muted"> · ${context.sampleState}</span></span></p></div>${btn('查看委托','mission','small')}<div class="side-title">已知地点 <small>只读</small></div>${initial?note('出发后记录实际到达与观察。'):knownMap()}${btn('展开已知区域','map','small')}<div class="aside-bottom"><span class="loadout-summary">${tool?ITEMS[tool][0]:"工具未选"} / ${specialty?SPECIALTIES[specialty][0]:"专长未选"}</span><br>${initial?'中枢 · 出发准备':`${n[0]} / ${n[1]}`}<br>正式结束后不能重接本委托。</div></aside>
<section class="center" aria-label="中央内容区">${img(initial||(context.closed&&!dead)?'bg_elevator_hub_v01.png':n[2],initial?'真正电梯中枢':`${n[0]}${n[1]}场景`,'scene-bg').replace('class="scene-bg"',`class="scene-bg" style="object-position:${focal()[0]}% ${focal()[1]}%"`)}<div class="scene-shade"></div>${scene()}${sceneOnly?'':content()}</section>
<aside class="sidebar right metal ${drawer==='right'?'open':''}">${btn('关闭携带栏','drawer:none','small drawer-close')}<div class="spread side-title"><span>携带区</span>${btn('整理','inventory','small flat')}</div><div class="row carry-tabs">${btn('背包','carry:backpack','small '+(carryTab==='backpack'?'selected':''))}${btn('装备','carry:equipment','small '+(carryTab==='equipment'?'selected':''))}</div>${carryTab==='equipment'?equipment():`<div class="spread"><h3>背包 <small>6 × 4</small></h3><small>${designWeight()} / 28</small></div>${grid()}<div class="muted">仅背包计负重；装备与快捷分开。</div><div class="note" style="font-size:13px">任务件占用真实格位。2×2样本不是额外的关键物栏。</div>`}<div class="quick-area"><div class="side-title">快捷位</div>${quick()}</div><div class="aside-bottom">${context.error?'等待可靠记录；物品操作不可用。':initial?'初配：金属管、外套、所选工具、快捷绷带1。':'点击物品查看；右键或 Shift+F10 打开操作。'}</div></aside>
<footer class="footer metal"><span class="teal">${saveLabel()}</span><span class="feedback" aria-live="polite">${feedback}</span>${btn(active.kind==='save'&&['failed','retry'].includes(variant())?'只重试保存':'查看反馈',active.kind==='save'?'retry-save':'save','small flat')}<span class="draftlabel">${context.mode} · ${active.id}</span></footer></div>
<div class="designer">${btn('设计状态索引','review','')}<button data-export="svg">导出可编辑SVG</button><button data-export="png">导出PNG图稿</button><button data-local-export="yes">本地导出当前</button><button data-batch="all">本地导出全部</button></div>`;}
function saveLabel(){if(context.error)return '当前记录未就绪';return ({saved:'已保存','not-attempted':'尚无新写入',failed:'已生效 · 未保存',retry:'保存重试'})[context.save]||'已保存';}

function scene(){if(active.kind!=='explore'&&!sceneOnly)return '';const n=node(),isHub=['setup','hub','terminal','error'].includes(active.kind);if(isHub)return `<div class="scene-heading"><div><p class="eyebrow">ELEVATOR / 中枢</p><h1>电梯中枢</h1></div></div>`;let actions=btn('调查当前地点','node:records','gold')+btn('查看物资','search');if(active.node==='H1')actions=btn('搜索大厅','search','gold')+btn('处理消防门','node:door');if(active.node==='H0')actions=btn('查看返回条件','confirm:return','gold');if(active.node==='P0')actions=btn('查看已知路线','map');if(active.node==='T0')actions=btn('前往林岑安置点 · 2精力','npc:lin','gold');if(active.node==='L0'||active.node==='C0')actions=btn('查看已知路线','map');return `<div class="scene-heading"><div><p class="eyebrow">${isHub?'ELEVATOR / 中枢':`${n[0]} / 当前地点`}</p><h1>${isHub?'电梯中枢':n[1]}</h1></div><span class="tag">${isHub?'静态整备':'稳定地点'}</span></div><div class="scene-card" ${active.kind!=='explore'&&!sceneOnly?'inert aria-hidden="true"':''}><p class="scene-copy">${isHub?'门后的世界仍在等待。身体与家底留在这里，只有明确出发才进入委托。':active.id==='P04-after'?'你已到达酒店入口。这里与医院相连，后方仍是来时的路。':'冷光掠过旧墙。先确认眼前的条件，再决定下一步。'}</p><div class="scene-actions">${actions}${btn('休整说明',['H6','T1','L5','C4'].includes(active.node)?'rest:A':'rest:C')}${btn('已知地图','map')}</div><div class="direction"><span>相邻地点</span>${btn(active.node==='H0'?'酒店 / 入口 · 8精力':active.node==='T0'?'医院 / 电梯前室 · 8精力':'返回已知来路 · 2精力','cross','small')}</div></div>`;}
function panelTier(){
 if(active.kind==='item-detail')return 'detail';
 if(active.outcome)return 'brief';
 if(['confirm','save','error','help'].includes(active.kind))return 'brief';
 if(['medical','maintenance','npc','node','search'].includes(active.kind))return 'parameters';
 if(['result','terminal','rest','hub','mission'].includes(active.kind))return 'summary';
 return 'complex';
}
function panel(title,body,footer='',max=expanded){return `<section class="panel tier-${panelTier()} kind-${active.kind} ${max?'max':''}" role="region" aria-label="${escape(title)}"><header class="panel-title"><h2>${title}</h2><div class="tools">${btn(max?'还原':'放大','maximize','small flat')}${viewStack.length||!['setup','hub','terminal','error'].includes(active.kind)?btn('收起','close','small flat'):''}</div></header><div class="panel-body" tabindex="0" aria-label="可滚动内容">${body}</div>${footer?`<footer class="panel-footer">${footer}</footer>`:''}</section>`;}
function content(){const v=variant();switch(active.kind){
case 'explore':return '';
case 'setup':return panel('出发准备',`<div class="stack"><div><p class="eyebrow">一份委托 · 一次世界驻留</p><h1>封锁区 · 未完成的转运</h1><p class="muted">七个任务日内恢复供电与转运，携指定样本合法返回。</p></div><h3>选择工具 <small>三选一，与专长独立</small></h3><div class="choices">${['crow','lamp','toolbox'].map(k=>`<button data-act="tool:${k}" class="choice ${tool===k?'selected':''}">${itemImg(k)}<h3>${ITEMS[k][0]}</h3><p>${k==='crow'?'撬动障碍，消耗真实耐久。':k==='lamp'?'为可照明搜索供光，消耗电量。':'处理专门作业，消耗工具耐久。'}</p></button>`).join('')}</div><h3>选择专长 <small>本次驻留内不可改选</small></h3><div class="choices">${Object.entries(SPECIALTIES).map(([k,[name,desc]])=>`<button data-act="specialty:${k}" class="choice ${specialty===k?'selected':''}"><h3>${name}</h3><p>${desc}</p></button>`).join('')}</div>${note('固定初配：金属管、厚实外套、所选工具、快捷绷带1。没有额外初粮或药品。')}</div>`,`<small>${tool&&specialty?`已选 ${ITEMS[tool][0]} / ${SPECIALTIES[specialty][0]}`:'请分别选择工具与专长'}</small>${btn('确认配装','setup-ready','gold',tool&&specialty?'':'disabled')}`,true);
case 'hub':return panel('初次中枢 · 初配已锁定',`<div class="split">${art('bg_elevator_hub_v01.png','真正电梯中枢',true)}<div class="stack"><p class="eyebrow">出发前最后检查</p><h1>准备进入封锁区</h1>${facts([['工具',ITEMS[tool||'toolbox'][0]],['专长',SPECIALTIES[specialty||'engineer'][0]],['任务期限','7个任务日'],['完整成功','积分 +120']])}${note('只有当前这一份真实委托。正式成功或失败返回后，不能重接。')}</div></div>`,`<small>查看与整备不自动推进身体周期</small>${btn('明确出发','depart','gold')}`);
case 'search':return searchPanel();
case 'node':return nodePanel();
case 'npc':return npcPanel();
case 'mission':return panel('委托详情',`<div class="split">${art('objective_pathogen_case_v02.png','密封病原样本箱')}<div class="stack"><p class="eyebrow">封锁区 · 未完成的转运</p><h2>供电、转运、指定样本</h2>${facts([['本地供电',context.powerDone?'已完成':'未完成'],['转运设施',context.transferDone?'已完成':'尚未安装'],['样本状态',context.sampleState],['完整成功','合法H0返回，积分120']])}${note('设施作业不等于安装。样本取得不等于携回；地面样本不能满足成功条件。')}${context.closed||context.dead?note('已关闭委托的交付历史，只读；不能继续履约。'):btn('查看完整返回条件','confirm:return')}</div></div>`,`<small>任务说明为当前设计呈现；数值来自已批规则</small>${btn('返回当前上下文','close')}`);
case 'map':return panel('已知区域 · 只读',`<div class="stack" style="height:100%"><div class="spread"><p class="eyebrow">${node()[0]} / 已获知识</p><span class="tag">${v==='last-observed'?'远端为上次观察':'当前：'+node()[1]}</span></div>${knownMap(true)}<div class="maplegend"><span><i></i>当前地点</span><span>空心节点：已知地点</span><span>虚线：已知受阻</span></div>${note('只显示已经到达或观察到的节点与连接。点击地图不会移动；实际移动在场景方向区执行。')}</div>`,`<small>远端信息不会自动更新</small>${btn('返回场景','close')}`);
case 'item-detail':return panel(ITEMS[active.item][0],`<div class="split">${art(active.item==='sample'?'objective_pathogen_case_v02.png':ITEMS[active.item][1],ITEMS[active.item][0])}<div class="stack"><h1>${ITEMS[active.item][0]}</h1>${facts([['占格',ITEMS[active.item][2]+'×'+ITEMS[active.item][3]],['查看','不消耗、不搬运'],['操作','返回后使用明确的容器操作']])}${note('数量与剩余资源属于选中的真实实例；此独立图稿不代表新增实物或默认初配。')}</div></div>`,btn('返回上下文','close'));
case 'inventory':return panel('装备与背包',`<div class="split"><div class="stack"><h3>实际6 × 4格位</h3>${grid()}${quick()}<p class="muted">2×2样本、1×2急救包与1×1普通物共同占位。</p>${btn(active.rotated?'还原旋转示范':'查看旋转占格','rotate-demo')}</div><div class="stack">${equipment()}${facts([['整理','明确实例与目标格位'],['快捷','独立迁移，不复制实物'],['旋转','只改占格，不拉扁图像']])}${btn('打开搬运参数','organize:move','gold')}</div></div>`);
case 'organize':return organizePanel();
case 'medical':return medicalPanel();
case 'maintenance':return maintenancePanel();
case 'rest':return panel('休整与跨日',`<div class="stack"><p class="eyebrow">${node()[0]} / ${node()[1]}</p><h1>${v==='death'?'本期结算中实际死亡':v==='consequences'?'本期后果已结清':`${v==='A'?'A':'C'}类合法休整`}</h1>${facts(v==='death'?[['生命','0'],['后段处理','已短路'],['角色周期','不虚增']]:[['精力重设目标',v==='A'?'100':'85'],['身体顺序','流血 → 感染 → 饥饿'],['治疗与维护','不会自动发生']])}${note(v==='death'?'死亡不是失败召回；不能用药复活。':'有待战斗或立即结果时不能休整。HP0立即停止后段；生还才结束周期药效并推进周期。')}${v==='consequences'?note('这是已结结果样张，不是下一次日结的精确预测。'):''}</div>`,`<small>休整不自动回血、止血或补给</small>${btn(v==='death'?'切换独立死亡结果样例':v==='consequences'?'返回现场':'执行合法休整',v==='death'?'screen:P21-enemy-alive':v==='consequences'?'close':'demo:休整结果示范已记录','gold')}`);
case 'battle':return battlePanel();
case 'result':return panel(v==='victory'?'战斗胜利':'退却完成',`<div class="terminal"><div class="result-mark"><span>${v==='victory'?'✓':'↶'}</span></div><h1>${v==='victory'?'眼前的危险解除':'回到入场前地点'}</h1>${facts([['当前地点',node()[0]+' / '+node()[1]],['探索精力','按本场实际经过一次结算'],['装备与身体','保留真实消耗与伤势'],['任务样本','不由战斗自动掉落']])}<p>${v==='victory'?'胜利不是委托完成。后续仍须实际行动。':'敌人残余状态持续；再入不会刷新物资或身体。'}</p></div>`,`<small>本页为已结结果设计样例</small>${btn('查看当前现场','close','gold')}`);
case 'terminal':return terminalPanel();
case 'confirm':return confirmPanel();
case 'save':return panel('保存状态',`<div class="errorbox"><p class="eyebrow">当前页面 / 持久化状态</p><h1>${saveLabel()}</h1><p>${['failed','retry'].includes(v)?'本次行动已在当前页面生效。保存失败不会撤销身体、物品、任务或积分结果。':v==='saved'?'最新完整状态已写入。':'当前页面没有发起新的写入；查看界面不产生玩法提交。'}</p>${note('只重试保存，不再执行原行动。刷新或关闭后，只能恢复最后成功保存的记录。')}</div>`,`<small>重试不会重新发放、扣款或抽取</small>${btn('只重试保存','retry-save','gold',v==='saved'||v==='not-attempted'?'disabled':'')}`);
case 'error':return errorPanel();
case 'help':return helpPanel();
default:return '';
}}
function searchPanel(){const v=variant();return panel('大厅 · 物资查看',`<div class="split">${art('bg_emergency_hall_v01.png','大厅来源场景',true)}<div class="stack"><p class="eyebrow">${v==='unsearched'?'尚未搜索 · 不预告未知物资':'一次来源 · 已揭示结果'}</p><h2>${v==='empty'?'这里已经取空':v==='unsearched'?'确认搜索方式':'地面可见物'}</h2>${v==='unsearched'?`<div class="form">${fields('照明方式',['不使用照明 · 基础12精力','使用当前合格手电 · 基础8精力，电量1'],'light')}</div>${note('这里没有“可能获得”物资货架；搜索后才显示真实结果。')}`:v==='empty'?note('原来源已经耗尽。重新打开不会重抽或补发。'):`<div class="equip">${itemImg('metal')}<div>金属零件 ×1<small style="display:block">已揭示 · 地面实物</small></div></div><div class="equip">${itemImg('battery')}<div>通用电池 ×1<small style="display:block">本样张已抽到的分支，不是必得预告</small></div></div>${btn('拾取整个金属零件实例','demo:整实例拾取示范，先检验合法容量')}`}</div></div>`,`<small>${v==='reopen'?'再次查看沿用同一已揭示结果':'具体成本由完整当前请求预览'}</small>${btn(v==='unsearched'?'执行搜索':'收起',v==='unsearched'?'search-submit':'close','gold',v==='unsearched'?'data-needs="light" disabled':'')}`);}
function nodePanel(){const v=active.method?'sample-'+active.method:variant();if(active.outcome)return panel(active.title,`<div class="stack"><p class="eyebrow">已结公开结果 · 独立设计样例</p><h1>${active.outcome}</h1>${note('保持真实余量与来源状态；重新查看不会重复执行、产物或扣耗。')}${note('这是结果版式示例，不是生产规则运行记录。')}</div>`,btn('返回当前地点','close','gold'));const config={door:['event_isolation_fire_door_v02.png','通路仍被消防门阻挡',['撬棍 · 基础6精力，消耗耐久','工具箱 · 基础10精力，消耗耐久','门禁卡 · 基础4精力'],'首次工具箱处理的电子材料留在地面，须另行拾取。'],power:['closeup-power-v1.png','先调查，再恢复当地支路',['完成支路调查 · 基础6精力','已调查后恢复供电 · 基础12精力'],'供电完成是任务事实，不等于转运已经安装。'],records:['closeup-records-v1.png','核对真实记录',['完整核对 · 基础6精力','已有匹配条件的快核 · 基础4精力'],'侦察采用已批4/3精力，不免费揭示隐藏路线。'],component:['closeup-component-v1.png','核对、解除固定，再实际取件',['按已知方法解除固定 · 基础10精力','普通手工作业 · 基础14精力（工程10）','撬棍解除固定 · 基础6精力，耐久1','实际提取组件 · 基础10精力'],'任务件必须指定真实2×2放置，不能自动挤入背包。'],'sample-cautious':['objective_pathogen_case_v02.png','谨慎提取指定样本',['谨慎提取 · 基础10精力','直接提取 · 基础6精力'],'需要当前合法来源、真实防护状态和明确2×2格位。'],'sample-direct':['objective_pathogen_case_v02.png','直接提取指定样本',['谨慎提取 · 基础10精力','直接提取 · 基础6精力'],'直接与谨慎的代价、暴露风险不同；不标为绝对安全。'],install:['closeup-install-v1.png','为转运平台装接',['使用所选真实任务专件与材料 · 基础12精力'],'整笔检查后同时消耗组件、模块、金属1、电子1；不先扣一半。']}[v]||null;if(!config)return '';return panel(active.title,`<div class="split ${v.startsWith('sample')?'sample-layout':''}">${v.startsWith('sample')?`<div class="stack sample-payment-slot">${art(config[0],active.title)}${samplePayment()}</div>`:art(config[0],active.title,true)}<div class="stack"><p class="eyebrow">${node()[0]} / ${node()[1]}</p><h2>${config[1]}</h2><div class="form">${fields('明确操作方案',config[2],'method')}${v==='install'?fields('实际材料实例',['金属零件实例A + 电子元件实例B'],'materials'):''}${v.startsWith('sample')||v==='component'?`${fields('目标位置',['背包第1列第1行 · 2×2','背包第4列第2行 · 2×2'],'placement')}`:''}</div>${note(config[3])}<p class="muted">当前已知成本见方案；完整意图一次执行。低精力不能代替其他条件。</p></div></div>`,`<small id="parameter-note">请明确所需参数</small>${btn('执行所选操作','node-submit','gold','data-needs="method" disabled')}`);}
function npcPanel(){const lin=active.person==='lin';return panel(lin?'林岑 · 安置点':'周衡 · 休息室',`<div class="split">${art(`npc-${lin?'lin':'zhou'}-v1.png`,lin?'林岑形象候选':'周衡形象候选')}<div class="stack"><p class="eyebrow">${node()[0]} / ${node()[1]}</p><h1>${lin?'有限的现场交换':'了解解除固定的方法'}</h1><p class="body-copy">${lin?'这里可以进行已声明的一次交换：真实绷带1与消毒剂1，换取压缩口粮2。':'调查现有作业方法。获得方法不等于已经解除固定，也不会直接给予任务件。'}</p>${lin?`<div class="form">${fields('选择绷带实例',['背包绷带实例'],'bandage')}${fields('选择消毒剂实例',['背包消毒剂实例'],'disinfectant')}${fields('口粮目标位置',['背包第4列第2行'],'placement')}</div>`:facts([['调查成本','基础4精力'],['作用','既有方法事实'],['额外奖励','无']])}${note('人物外观是呈现候选。此处没有商店、额外支线或对话树。')}</div></div>`,`<small>${lin?'结果容量须预先满足':'正式行为仍由当前合法意图决定'}</small>${btn(lin?'执行一次交换':'调查方法','npc-submit','gold',lin?'data-needs="bandage,disinfectant,placement" disabled':'')}`);}
function organizePanel(){
 const v=variant(),o=selectedObject,needs=['instance',...(['move','task-pickup','split'].includes(v)?['cell']:[]),...(v==='split'?['quantity']:[]),...(['merge','quick'].includes(v)?['target']:[])];
 const candidates=(['task-pickup','no-space'].includes(v)?context.groundItems:context.items).filter(i=>v!=='split'||STACKABLE.has(i.key)&&i.quantity>1);
 const instanceField=o?`<p class="note">当前对象：${ITEMS[o.key][0]} · ${o.quantity}单位<br>来自${o.container==='backpack'?'背包':o.container==='equipment'?'装备':o.container==='quick'?'快捷位':'当前地点来源'}，操作全过程保持同一对象。</p>`:`<label>明确原实例<select data-field="object"><option value="">请选择</option>${candidates.map(i=>`<option value="${i.ref}">${ITEMS[i.key][0]} · ${i.quantity}单位 · ${i.container==='ground'?'当前地点地面':'第'+(i.x+1)+'列第'+(i.y+1)+'行'}</option>`).join('')}</select></label>`;
 return panel(active.title,`<div class="split"><div class="stack"><h3>${v==='drop'?'当前容器 · 留置前':'目标容器 · 实际占格'}</h3>${grid(v!=='drop')}<div class="row">${['move','task-pickup','split'].includes(v)?btn('旋转占格','rotate-placement','small',o?'':'disabled'):''}<span id="placement-label" class="muted">${o?o.w+'×'+o.h+' · ':''}尚未选择目标格位</span></div>${note(v==='no-space'?'当前没有合法2×2位置。物品仍在原地；没有领取或扣耗。':'明确格位，不自动整理其他物品；移动时不把原实例当作新物品。')}</div><div class="form">${o?art(o.key==='sample'?'objective_pathogen_case_v02.png':ITEMS[o.key][1],ITEMS[o.key][0]):note('先选择当前上下文中的实际对象。')}${instanceField}${v==='split'&&o?`<label>拆出数量<input data-field="quantity" type="number" min="1" max="${o.quantity-1}" placeholder="1—${o.quantity-1}" value="${chosen.quantity||''}"></label>`:''}${v==='merge'?fields('接收实例',context.items.filter(i=>o&&i.key===o.key&&i.ref!==o.ref).map(i=>ITEMS[i.key][0]+' · 第'+(i.x+1)+'列'+(i.y+1)+'行'),'target'):''}${v==='quick'?fields('目标快捷位',['快捷位1','快捷位2'],'target'):''}<p class="muted">${v==='drop'?'当前物件将留在实际地点。关键任务物使用适用确认。':'只编排显式参数，不运行库存规则或修改真实实物。'}</p></div></div>`,`<small id="parameter-note">${v==='no-space'?'没有合法位置':o?'已绑定 '+ITEMS[o.key][0]:'等待选择对象'}</small>${btn('提交本次整理','organize-submit','gold',`disabled data-needs="${needs.join(',')}"`)}`);
}
function medicalPanel(){const k=selectedObject?.key||active.item||'bandage', info={bandage:['恢复生命并止血','有未处理伤口时须选择一处；本样张有合格伤口。'],firstaid:['恢复最多4生命并处理明确目标','不自动清除全部轻伤；恢复按上限封顶。'],ration:['饱食恢复2，按上限封顶','不恢复生命；仅战外稳定点使用。'],painkiller:['抑制声明的挫伤／伤口惩罚','不治疗、不删除伤口，药效按周期结束。'],disinfectant:['处理待暴露','不减少既成感染；隐藏目标可能仍无法判断。'],suppressant:['设置既有抑制效果','不直接治愈；读取或休整入口不会随意刷新额度。']}[k];return panel(active.title,`<div class="split">${art(ITEMS[k][1],ITEMS[k][0])}<div class="stack"><p class="eyebrow">${active.battle?'战斗 / 真实快捷位1':'战外稳定点 / E0也须合格'}</p><h1>${ITEMS[k][0]}</h1><p>${info[0]}</p>${facts([['数量','本次1单位'],['资格',active.invalid?'无合格目标':active.unknown?'尚不能判断（unknown）':'存在合格目标'],['入口',active.battle?'只限快捷绷带与镇痛':'稳定点药食']])}<div class="form">${fields('物品实例',[(selectedObject?.container==='quick'?'快捷位1':'背包')+' · '+ITEMS[k][0]+' · 当前明确对象'],'medicine')}${['bandage','firstaid'].includes(k)?fields('明确处理目标',['左前臂 · 未处理开放伤口','仅恢复生命（目标允许时）'],'wound'):''}</div>${note(active.invalid?'不会先消耗药物。请检查当前状态。':info[1])}</div></div>`,`<small>${active.unknown?'当前粗档不等于治疗资格证明':'当前操作不批量治疗或自动选目标'}</small>${btn('使用一次','medical-submit','gold','data-needs="medicine" disabled')}`);}
function maintenancePanel(){const v=variant(),k=v==='coat'?'coat':v==='toolbox'?'toolbox':v==='charge'?'lamp':'pipe';return panel(active.title,`<div class="split">${art(ITEMS[k][1],ITEMS[k][0])}<div class="stack"><h2>${v==='mechanical'?'一次机械总池 · 15点':'明确设备与真实材料'}</h2><div class="form">${fields('材料实例',v==='coat'?['织物材料实例']:v==='charge'?['兼容通用电池实例']:v==='toolbox'?['金属实例 + 电子实例']:['金属零件实例'],'materials')}${v==='mechanical'?'<label>分配给金属管<input type="number" min="0" max="15" data-field="pipe" placeholder="0—15"></label><label>分配给撬棍<input type="number" min="0" max="15" data-field="crow" placeholder="0—15"></label>':fields('目标设备',[ITEMS[k][0]+' · 真实未满资源实例'],'equipment')}</div>${facts([['基础精力',v==='toolbox'?'8':v==='charge'?'4':'6'],['恢复',v==='mechanical'?'两目标合计≤15':v==='coat'?'6，按上限封顶':v==='toolbox'?'3，按上限封顶':'4，按上限封顶']])}${note('维护不治疗身体、不刷新日额、不生成任务材料。E0不能开始维护。')}</div></div>`,`<small id="parameter-note">等待材料与目标分配</small>${btn('执行本次维护','maintenance-submit','gold','data-needs="materials" disabled')}`);}
function battlePanel(){const enemy=active.enemy||'orderly',phaseText=({'submitted':'玩家行动已提交 · 演出示范','enemy-response':'敌人响应 · 已结事件示范','retreat':'合法退却已提交 · 过程示范','hit':'命中瞬间 · 已结事件示范'})[variant()]||'等待你的选择',name={orderly:'感染护工',porter:'感染装卸工',technician:'感染技术员'}[enemy];if(active.phases)return panel(name+' · 五公开阶段',`<p class="muted">同一主体与阶段组；透明画布、脚底和命中锚须共同核对。</p><div class="stage-list">${STAGES.map((s,i)=>`<figure>${img(enemyFile(enemy,i),name+s)}<figcaption>${s}</figcaption></figure>`).join('')}</div>`,`${btn('切换独立战斗样例','screen:P15-'+enemy,'gold')}`);
return `<section class="panel battle ${expanded?'max':''}" role="region" aria-label="战斗面板"><header class="panel-title"><div><h2>${node()[0]} · ${node()[1]}</h2><small>战斗进行中 · 查看不推进CTB</small></div><div class="tools">${btn(expanded?'还原':'放大','maximize','small')}${btn(reduced?'恢复动态':'减少动态','reduce','small')}</div></header><div class="timeline"><span>相对行动顺序</span><div class="track"><span class="token enemy">敌</span><span class="token player">你</span></div><span class="decision">${phaseText}</span></div><div class="arena ${active.hit?'hit':''}">${img(node()[2],'当前遭遇背景','bg')}${actorVisual('player-back-v2.png','玩家背身','player')}${actorVisual(enemyFile(enemy,stage),`${name} · ${STAGES[stage]}`,'enemy')}<div class="actor-caption left">你 · 生命8/12</div><div class="actor-caption right">${name} · <span id="enemy-stage">${STAGES[stage]}</span></div><div class="intent">当前意图：普通攻击<br><span class="muted">速度正常 · 中等直接伤害</span></div></div><div class="battle-actions">${btn('普通攻击<small>金属管耐久 −1</small>','attack-demo','gold')}${btn('标志行动<small>真实额度与耐久</small>','signature-demo')}${btn('防御<small>姿态示范 · 不伤敌</small>','defend-demo')}${btn('快捷绷带<small>槽1 · ×1</small>','medical-battle')}${btn('合法退却<small>返回入场前节点</small>','retreat','danger')}</div><div class="battle-feed"><span>精力在胜利或退却后按本场经过一次结算。</span>${btn('通用受击FX','hit-demo','small')}<small>演出示范 · 不计算伤害</small></div></section>`;}
function terminalPanel(){const f=active.family,success=f==='P18',dead=f==='P21',deadline=f==='P20';return panel(dead?'角色死亡':'委托已结束',`<div class="terminal"><p class="eyebrow">封锁区 · 未完成的转运</p><div class="result-mark"><span>${success?'✓':dead?'×':'—'}</span></div><h1>${success?'转运完成，样本已交付':dead?'生命归零':'失败生还，委托已关闭'}</h1><div class="balance">${success?'+120':dead?'0':deadline?'0':'−20'} <span style="font-size:18px">积分</span></div>${facts(success?[['本地供电 / 转运','均已完成'],['指定样本','原实例交付一次'],['普通携出物','保留真实数量与资源'],['当前去处','静态中枢']]:dead?[['本次收入','0'],['失败罚款','不另扣20'],['当前可用家底','不可用、不可向新角色继承'],['敌人结果',variant()==='both-zero'?'双方失去能力':'敌人仍存活']]:[['本次收入','0'],['实际罚款',deadline?'当前余额0 → 实扣0':'余额35 → 15 · 仅扣20一次'],['普通携出物','保留真实剩余状态'],['身体周期',deadline?'当期后果已结，生还才召回':'H0正常返回，不补夜']])}<p>${dead?'已经发生的交付、安装与消费历史不会被改写。':deadline?'不生成Day8，不重复结算本周期。当前没有下一份真实委托。':'本委托不能重接；当前没有下一份真实委托。'}</p></div>`,`<small>${dead?'不提供复活或新角色入口':'生还角色继续存在；中枢不自动治疗或推进病情'}</small>${btn('查看结果说明','help:health')}`);}
function confirmPanel(){const v=variant();return panel(v==='stale'?'原选择已失效':'请确认当前决定',`<div class="errorbox"><p class="eyebrow">${v==='cancelled'?'已取消 / 未执行':v==='stale'?'当前条件已变化':'仅适用的敏感保护'}</p><h1>${v==='critical-drop'?'将'+(selectedObject?ITEMS[selectedObject.key][0]:'指定样本')+'留在这里？':v==='certain-death'?'本次操作确定导致死亡':v==='stale'?'重新选择实例与参数':v==='cancelled'?'仍在原来的现场':'正式返回会结束本委托'}</h1><p>${v==='critical-drop'?'离开后仍须真实回访才能取回；正式关闭委托后，地面物不再可访问。':v==='certain-death'?'当前还有不保证死亡的合法替代行动。你可以返回检查身体或重新选择。':v==='stale'?'没有替你换成第一件物品，也没有提交旧参数。':v==='cancelled'?'取消没有消耗精力、物品或关闭委托。':'当前未完整履约。合法失败返回本次收入0，仅扣min(当前积分,20)，不能回中枢后补做。'}</p>${note('普通完整行动不套用本确认。该样张只覆盖当前适用的终局、关键物或必死保护。')}</div>`,`${btn('取消并返回','close')}${btn(v==='stale'?'重新选择':'确认当前意图',v==='stale'?'organize:move':'demo:敏感确认设计演示；未接真实玩法','gold',v==='cancelled'?'disabled':'')}`);}
function errorPanel(){const v=variant(),texts={request:['正在取得使用权','等待本页成为唯一使用页。不会另建角色或默认补发物品。'],occupied:['另一页面正在使用','请在正在使用的页面继续；本页当前不能执行玩法。'],lost:['本页已失去使用权','旧参数已失效。不要继续提交或把旧画面当最新状态。'],corrupt:['记录无法校验','这不是空记录。保留原记录，不清档、不发初始物品。'],'read-error':['暂时无法读取','不会用默认状态替代真实记录。可以只重试读取。'],projection:['展示暂不可用','没有可靠的当前画面，停止提供玩法按钮；不因此判定角色死亡。']}[v];return panel('启动与异常',`<div class="errorbox"><p class="eyebrow">页面状态</p><h1>${texts[0]}</h1><p>${texts[1]}</p>${note('恢复、锁与保存由后续正式接线负责。本设计原型不读写任何玩家记录。')}</div>`,`<small>原记录保留；没有重置入口</small>${btn(v==='read-error'?'只重试读取':'查看说明','help:controls','gold')}`);}
function helpPanel(){const v=variant();return panel('操作与机制说明',`<div class="subnav">${btn('操作','help:controls','small')}${btn('身体与药食','help:health','small')}${btn('快捷位','help:quick','small')}</div><div class="body-copy">${v==='health'?'<h2>公开病程不是精确预测</h2><p>当前病程粗档只描述现在的公开负担。低档不代表没有隐藏暴露，也不能据此断言药品一定有效或下一次结算安全。</p><h3>合法稳定点的自救</h3><p>仍须有真实物品与合格目标。HP0不能用药复活。中枢查看不会自动治疗、进食或推进病情。</p>':v==='quick'?'<h2>两个真实快捷位</h2><p>迁移会改变真实实例所在容器，不会复制背包里的物品。空槽不会自动补药。</p><p>战中只允许真实快捷槽的绷带和镇痛；能装入快捷槽不等于能在战斗中使用。</p>':'<h2>先看清，再作决定</h2><p>查看任务、地图、物品与放大面板不消耗行动。地图只读，移动从场景方向区逐边执行。</p><h3>需要参数时明确选择</h3><p>方法、材料、目标实例和格位由你选择。条件变化后旧选择失效，系统不会无声替换成第一项。</p><h3>键盘操作</h3><p>Tab移动焦点，Enter或空格激活。Escape关闭可收起的信息层；战斗不能用Escape结束。物品支持右键与Shift+F10菜单。</p>'}</div>`,`${btn('返回','close')}`);}

function render(){document.title=`${active.title} · 电梯求生 UI设计`;$('#app').innerHTML=shell();mountNineSlice();if(qs.get('qa')==='corners'){const test=document.createElement('aside');test.setAttribute('aria-label','设计测试：四角菜单');test.innerHTML=['左上','右上','左下','右下'].map((n,i)=>`<button class="item" data-act="item:bandage" aria-label="${n}测试物品" style="position:fixed;z-index:45;width:48px;height:48px;${i%2?'right:0;left:auto':'left:0'};${i<2?'top:0':'bottom:0;top:auto'}">${n}</button>`).join('');document.body.append(test);}wire();}
function navigate(id){selectSample(id);}

function openKind(origin,kind,id){const next=SCREENS.find(s=>s.kind===kind&&(id?s.id===id:true));openView(origin,next);}

function toast(text){feedback=text;const f=$('.feedback');if(f)f.textContent=text;}
function parameters(){document.querySelectorAll('[data-needs]').forEach(b=>{const keys=b.dataset.needs.split(',');b.disabled=!keys.every(k=>chosen[k]!==undefined&&chosen[k]!=='')||!!active.invalid||active.id==='P11-no-space';});}
function wire(){
 document.querySelectorAll('[data-act]').forEach(b=>b.addEventListener('click',()=>act(b.dataset.act,b)));
 document.querySelectorAll('[data-field]').forEach(e=>e.addEventListener('input',()=>{
  chosen[e.dataset.field]=e.value;
  if(e.dataset.field==='object'){selectedObject=[...context.items,...context.groundItems].find(i=>i.ref===e.value)||null;chosen.instance=selectedObject?.ref;chosen.cell=undefined;render();parameters();}
  else if(e.dataset.field==='method'&&active.id.startsWith('P06-sample-')){document.querySelector('.sample-payment')?.remove();const target=document.querySelector('.sample-payment-slot');target?.insertAdjacentHTML('beforeend',samplePayment());}
  parameters();
 }));
 document.querySelectorAll('.item,.equip').forEach(b=>{b.addEventListener('contextmenu',e=>{e.preventDefault();menu(e.clientX,e.clientY,b);});b.addEventListener('keydown',e=>{if(e.shiftKey&&e.key==='F10'){e.preventDefault();const r=b.getBoundingClientRect();menu(r.left,r.top,b);}});});
 parameters();
}
function menu(x,y,origin){
 document.querySelector('.context')?.remove();lastFocus=origin;const object=currentObject(origin);if(!object)return;
 const canEdit=!context.dead&&!context.error&&!context.closed&&context.domain==='stable';
 const el=document.createElement('div');el.className='context';el.setAttribute('role','menu');
 el.innerHTML=`<small>${escape(ITEMS[object.key][0])} · ${object.quantity}单位</small>`+btn('查看详情','item:'+object.key)+(canEdit?btn('明确移动','organize:move')+btn('留在当前地点','organize:drop')+(STACKABLE.has(object.key)&&object.quantity>1?btn('拆分','organize:split'):''):'')+(MEDICINES.has(object.key)&&!context.dead&&!context.error&&!context.closed?btn('使用此物品','use-selected'):'')+btn('关闭菜单','menu-close');
 document.body.append(el);const r=el.getBoundingClientRect();el.style.left=Math.max(8,Math.min(x,innerWidth-r.width-8))+'px';el.style.top=Math.max(8,Math.min(y,innerHeight-r.height-8))+'px';
 el.querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{if(b.dataset.act==='menu-close'){act('menu-close');return;}el.remove();if(b.dataset.act.startsWith('organize:'))startOrganize(b.dataset.act.split(':')[1],origin,object);else if(b.dataset.act==='use-selected')showSelectedMedicine(origin,object);else openView(origin,{...active,kind:'item-detail',id:'P10-detail-'+object.key,item:object.key},object);}));el.querySelector('button').focus();
}

function act(a,b){const [verb,val]=a.split(':');if(context.error&&!['review','maximize','help','drawer','close','menu-close','map'].includes(verb)){toast('当前记录未就绪，不能操作。');return;}if(context.dead&&['quick','organize','medical-battle','rest','confirm','node','search','cross','depart'].includes(verb)){toast('角色已死亡，实物不可用。');return;}switch(verb){
case 'review':{const e=document.createElement('section');e.className='review-menu';e.innerHTML=`<div class="spread"><h2>设计状态索引 · ${SCREENS.length}幅</h2>${btn('关闭索引','review-close')}</div><p class="muted">这里切换独立样例，会重置当前演示。样例内的查看、初选到出发及退却接续保留当前上下文。</p><nav>${SCREENS.map(s=>`<a href="?screen=${s.id}${qs.get('offline')==='1'?'&offline=1':''}">${s.id}<br>${s.title}</a>`).join('')}</nav>`;document.body.append(e);e.querySelector('button').onclick=()=>e.remove();break;}
case 'tool':if(context.domain==='setup'){tool=val;context.tool=val;render();}break;case 'specialty':if(context.domain==='setup'){specialty=val;context.specialty=val;render();}break;
case 'setup-ready':if(tool&&specialty&&context.domain==='setup'){active={...SCREENS.find(s=>s.id==='P02-first-hub')};context.domain='first-hub';context.mode='连续操作';viewStack=[];render();}break;case 'depart':if(context.domain==='first-hub'){context.domain='stable';context.initial=false;context.day=1;context.node='H0';contextNode='H0';active={id:'P03-first-arrival',family:'P03',kind:'explore',title:'医院 · 首次抵达电梯前室',node:'H0'};context.mode='连续操作';viewStack=[];render();}break;
 case 'maximize':expanded=!expanded;render();document.querySelector('[data-act="maximize"]')?.focus();break;
case 'close':closeView();break;
case 'map':if(context.error){toast('当前记录未就绪，没有可靠地图。');return;}if(context.initial){toast('出发后记录实际已知地点。');return;}openKind(b,'map');break;case 'mission':if(context.error)return;openKind(b,'mission','P08-carried');break;case 'inventory':if(context.error)return;openKind(b,'inventory');break;case 'search':if(context.domain!=='stable')return;openKind(b,'search');break;
case 'node':if(context.domain==='stable')openKind(b,'node','P06-'+val);break;case 'npc':openKind(b,'npc','P07-'+val);break;case 'organize':startOrganize(val,b,selectedObject);break;case 'help':openKind(b,'help','P25-'+val);break;case 'confirm':if(context.domain==='stable')openKind(b,'confirm','P22-'+val);break;case 'rest':if(context.domain==='stable')openKind(b,'rest','P14-'+val);break;case 'save':openKind(b,'save','P23-failed');break;case 'screen':toast('该按钮打开另一个独立设计样例，不是连续玩法。');navigate(val);break;
case 'carry':carryTab=val;render();break;
case 'drawer':drawer=val==='none'?null:val;render();break;
case 'item':{const object=currentObject(b);if(object)openView(b,{...active,kind:'item-detail',id:'P10-detail-'+val,item:val},object);break;}
case 'quick':if(val==='empty'){toast('空快捷位；没有默认补入物品。');return;}showSelectedMedicine(b,currentObject(b));break;
case 'medical-battle':showSelectedMedicine(b,{key:'bandage',ref:context.sampleId+'-quick-1',container:'quick',quantity:1,w:1,h:1});break;
case 'cross':if(context.domain!=='stable')return;if(context.node==='H0'||context.node==='T0'){context.node=context.node==='H0'?'T0':'H0';contextNode=context.node;active={...SCREENS.find(s=>s.id===(context.node==='T0'?'P04-after':'P04-before'))};context.mode='连续操作';viewStack=[];toast('单边到达的设计接续；不运行精力或风险结算。');render();}else toast('当前已知来路的单边移动；此审阅样例不模拟路线推进。');break;
case 'search-submit':if(chosen.light!==undefined){active={...active,id:'P05-revealed'};render();toast('搜索结果版式示范；未抽取随机或更换身体/配装。');}break;
case 'node-submit':if(!chosen.method){toast('请明确所需方案。');return;}if((active.id.includes('sample')||active.id.includes('component'))&&!chosen.placement){toast('任务件必须明确目标格位。');return;}if(active.id.endsWith('install')&&!chosen.materials){toast('请选择真实材料。');return;}toast('完整意图设计示范；没有执行生产规则。');break;
case 'npc-submit':toast('已有现场行为的设计示范；没有生成新商品或支线。');break;
case 'cell':{
 if(!selectedObject){toast('请先明确原实例。');return;}const cell=Number(val),x=cell%6,y=Math.floor(cell/6),size=chosen.rotated?[selectedObject.h,selectedObject.w]:[selectedObject.w,selectedObject.h];
 const occupied=context.items.filter(i=>variant()!=='move'||i.ref!==selectedObject.ref);
 const valid=x+size[0]<=6&&y+size[1]<=4&&!occupied.some(i=>x<i.x+i.w&&x+size[0]>i.x&&y<i.y+i.h&&y+size[1]>i.y);
 chosen.cell=valid?cell:undefined;document.querySelectorAll('.selection-grid .slot').forEach((e,i)=>{const inside=i%6>=x&&i%6<x+size[0]&&Math.floor(i/6)>=y&&Math.floor(i/6)<y+size[1];e.classList.toggle('chosen',inside&&valid);e.classList.toggle('invalid',inside&&!valid);});
 $('#placement-label').textContent=`${ITEMS[selectedObject.key][0]} · ${size[0]}×${size[1]} · 第${x+1}列，第${y+1}行 · ${valid?'有效位置':'越界或占用'}`;parameters();break;
}
case 'rotate-placement':chosen.rotated=!chosen.rotated;chosen.cell=undefined;document.querySelectorAll('.selection-grid .slot').forEach(e=>e.classList.remove('chosen','invalid'));$('#placement-label').textContent='朝向已变，请重新明确完整占格位置。';parameters();break;
case 'rotate-demo':toast('旋转独立样例位于设计索引；当前查看不更换携带内容。');break;
case 'organize-submit':if(!selectedObject){toast('请明确原对象。');return;}if(['move','task-pickup','split'].includes(variant())&&chosen.cell===undefined){toast('请明确目标格位。');return;}if(variant()==='split'&&(!Number.isSafeInteger(Number(chosen.quantity))||Number(chosen.quantity)<1||Number(chosen.quantity)>=selectedObject.quantity)){toast('拆出数量须为小于原堆叠的正整数。');return;}if(variant()==='drop'&&TASK_ITEMS.has(selectedObject.key)){openView(b,{...SCREENS.find(s=>s.id==='P22-critical-drop'),title:'留置'+ITEMS[selectedObject.key][0]+' · 关键物'},selectedObject);return;}toast(ITEMS[selectedObject.key][0]+'参数已明确；设计原型不修改实物。');break;
case 'medical-submit':if(['bandage','firstaid'].includes(active.item)&&!chosen.wound){toast('请选择明确的处理目标。');return;}toast(active.unknown?'语义示范：真实规则仍须验证隐藏目标，不把unknown写成安全。':'一次用药设计示范，不执行治疗或扣物。');break;
case 'maintenance-submit':if(variant()==='mechanical'){const x=Number(chosen.pipe),y=Number(chosen.crow);if(chosen.pipe===undefined||chosen.crow===undefined||!Number.isInteger(x)||!Number.isInteger(y)||x<0||y<0||x+y>15){toast('两目标分配必须明确且合计不超过15。');return;}}toast('维护分配设计示范；没有写入装备资源。');break;
case 'retry-save':toast('只保存重试示范：没有重放动作、发物或扣款。');break;
case 'reduce':reduced=!reduced;render();break;
case 'attack-demo':case 'signature-demo':case 'defend-demo':case 'hit-demo':{
 const ar=$('.arena'),tl=$('.timeline');if(!ar||context.domain!=='battle')return;clearTimeout(motionTimer);const epoch=flowSerial;
 if(verb==='defend-demo'){tl.classList.add('play');$('.decision').textContent='防御姿态 · 无敌人受击';ar.classList.add('defending');toast('防御动作示范；不造成敌人受击、不更换敌人战损。');}
 else{tl.classList.add('play');ar.classList.add('hit');$('.decision').textContent=verb==='hit-demo'?'通用命中FX · 无规则结算':'攻击演出示范 · 已结公开命中';toast(verb==='hit-demo'?'仅演示通用命中FX；不推进战损。':'独立攻击故事板：一次公开阶段切换；不是伤害计算。');}
 motionTimer=setTimeout(()=>{if(epoch!==flowSerial||!$('.arena'))return;if(['attack-demo','signature-demo'].includes(verb)){stage=Math.min(3,stage+1);$('.actor.enemy').outerHTML=actorVisual(enemyFile(context.enemy,stage),'当前敌人 · '+STAGES[stage],'enemy');$('#enemy-stage').textContent=STAGES[stage];}ar.classList.remove('hit','defending');tl.classList.remove('play');$('.decision').textContent='等待你的选择';},reduced?0:700);break;
}
case 'retreat':scriptedRetreat();break;
case 'menu-close':document.querySelector('.context')?.remove();lastFocus?.focus();break;case 'demo':toast(val);break;
}}
document.addEventListener('keydown',e=>{if(e.key==='Escape'){const m=document.querySelector('.context')||document.querySelector('.review-menu');if(m){m.remove();lastFocus?.focus();return;}if(!['battle','setup','hub','terminal','error'].includes(active.kind))act('close');}});
context=makeContext(screen);tool=context.tool;specialty=context.specialty;
render();
